// The base colour and the second in alternate cubes `square` mm on a side, moving with the object.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let c = floor(q / square);
let odd = ((i32(c.x) + i32(c.y) + i32(c.z)) & 1) == 1;
m.baseColor = select(m.baseColor, second, odd);

// worley3x -- two Worley lattices crossed, so the spangles keep to no grid: a spangle every `spangle`
// mm, each with its own grain direction in the object's xy (the anisotropy), and a roughness and
// brightness up to `spread` either side of the base ones.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let w = worley3x(q / spangle, 31u);
let a = 2.0 * PI * w.z;
m.tangent = grainAlong(R_local, vec3<f32>(cos(a), sin(a), 0.0));
m.roughness = m.roughness * (1.0 - spread + 2.0 * spread * fract(w.z * 13.0));
m.baseColor = m.baseColor * (1.0 - 0.5 * spread + spread * fract(w.z * 29.0));

// Turned on a lathe: circles about the object's own z axis through its origin.
// On the axis itself there is no direction (grainAround gives zero): the plain frame.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
m.tangent = grainAround(R_local, p_local, VEC3(0.0, 0.0, 1.0));
// The rings: each pass of the tool a little different. streakWidth and streakLength in mm,
// real size; streaks is how much the rings differ, 0 to 1.
let s = streaksAround(q, VEC3(0.0, 0.0, 1.0), streakWidth, streakLength);
m.roughness = m.roughness * mix(1.0 - 0.6 * streaks, 1.0 + 0.6 * streaks, s);
m.baseColor = m.baseColor * mix(1.0 - 0.1 * streaks, 1.0, s);

// Rings about an axis along the object's z -- the heart of the log, `heart` mm along x from the
// object's origin, so a board cut beside it shows arcs on its face and stripes on its edges --
// one every `ring` mm: the base colour (earlywood) darkening into latewood over the last
// `lateShare` of each, then starting again, as a year does. Gradient noise `wobbleSize` mm across
// (longer along z) bends them by `wobble` rings; fibres `fibre` mm wide and twenty times as long
// run along z.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let bend = gnoise3(q / vec3<f32>(wobbleSize, wobbleSize, 4.0 * wobbleSize), 7u).w;
let r = fract(length(q.xy - vec2<f32>(heart, 0.0)) / ring + wobble * bend);
let late = smoothstep(1.0 - lateShare, 1.0, r);
let fib = 0.5 + 0.5 * vnoise3(q / vec3<f32>(fibre, fibre, 20.0 * fibre), 8u).w;
m.baseColor = mix(m.baseColor, latewood, late) * (1.0 - fibreAmount + 2.0 * fibreAmount * fib);
m.roughness = min(1.0, m.roughness + 0.15 * late);

// Brushed along the object's own x: the strokes turn with the object (R_local).
// Positive anisotropy is smooth along the strokes and rough across them, so the
// highlight is drawn out ACROSS the strokes, as on real brushed metal.
m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// The lines: grooves of different depths, each a little rougher or smoother and darker or
// lighter than the next. streakWidth and streakLength in mm, real size whatever the scene's
// unit or the object's scale -- so on a metre-sized object seen whole they are too fine to see,
// as in life. streaks is how much the lines differ, 0 to 1.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let s = streaksAlong(q, VEC3(1.0, 0.0, 0.0), streakWidth, streakLength);
m.roughness = m.roughness * mix(1.0 - 0.6 * streaks, 1.0 + 0.6 * streaks, s);
m.baseColor = m.baseColor * mix(1.0 - 0.1 * streaks, 1.0, s);

// Material code: runs once per hit (cheap), after the fields above are put into m.
//   m        the Material2 to change -- m.baseColor, m.roughness, m.metallic, m.emissive, ...
//   p, n     the hit point and surface normal, world space;  C  the Hit
//   p_local  the hit in the object's own frame, so a pattern moves with the object
//            (costs one extra SDF evaluation per hit on this material)
//   R_local  that frame's rotation to the world, for a direction written in it
//   S_local  its scale: p_local * S_local is in scene units; metres(x) is x m in them, mm(x) x mm
//   your own parameters (+ in the parameters header) by name, e.g. a colour stripe; one marked
//            as a length is in real mm, whatever the scene's unit -- read the point in mm too:
//   let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
// e.g. a checker fixed in the world:
//   m.baseColor = mix(m.baseColor, VEC3(0.05), step(0.0, sin(p.x * 3.0) * sin(p.y * 3.0) * sin(p.z * 3.0)));
// e.g. stripes that travel with the object:
//   m.roughness = step(0.5, fract(p_local.x * 4.0)) * 0.6;
// e.g. brushed along the object's x, for an anisotropy above 0 (or turned: grainAround):
//   m.tangent = grainAlong(R_local, VEC3(1.0, 0.0, 0.0));
// e.g. with a length width (mm) and a colour stripe added with +, and q as above:
//   m.baseColor = mix(m.baseColor, stripe, step(fract(q.x / width), 0.5));

// Veins about `veinSpacing` mm apart, bent by five octaves of noise over `size` mm -- the stone's
// movement -- by `turbulence` spacings; `sharpness` is how thin a vein is, and `cloud` a soft grey
// between them, as Carrara has.
let q = p_local * S_local / mm(1.0)/size;   // the point in mm, moving with the object
let nz = fbm3(q  , 3u, 5u, 2.0, 0.5);
let v = pow(1.0 - abs(sin(PI * (q.x / veinSpacing + turbulence * nz.w))), sharpness);
let cl = 0.5 + 0.5 * fbm3(q / 0.5 , 4u, 3u, 2.0, 0.5).w;
m.baseColor = mix(mix(m.baseColor, vein, cloud * cl), vein, v);

// Five octaves of noise `patchSize` mm across: where it is in the top `coverage`, rust -- its
// shade varying on a fifth of that -- not a metal any more, rough and with a plain coat.
let q = p_local * S_local / mm(1.0);   // the point in mm, moving with the object
let f = 0.5 + 0.5 * fbm3(q / patchSize, 21u, 5u, 2.0, 0.5).w;
let r = smoothstep(1.0 - coverage - softness, 1.0 - coverage + softness, f);
let tone = 0.5 + 0.5 * vnoise3(q / (0.2 * patchSize), 22u).w;
m.baseColor = mix(m.baseColor, mix(rust, rustLight, tone), r);
m.metallic = m.metallic * (1.0 - r);
m.roughness = mix(m.roughness, rustRough, r);
m.specular = mix(m.specular, 0.5, r);

